window.AUTH=window.AUTH||{};window.AUTH["20-828"]={"d":"20-828","id":"2021/20-828","n":"Federal Bureau of Investigation v. Fazaga","briefs":[{"k":"respondent","label":"Brief of respondents Agents J. Stephen Tidwell and Barbara Walls in support of petitioners","date":"2021-07-30","url":"https://www.supremecourt.gov/DocketPDF/20/20-828/185452/20210730170834554_20-828%20ts.pdf","side":"res","n":56},{"k":"respondent","label":"Brief of respondents Agents Paul Allen, Kevin Armstrong, and Pat Rose in support of reversal","date":"2021-07-30","url":"https://www.supremecourt.gov/DocketPDF/20/20-828/185409/20210730122710323_2021.07.27%20Agent%20Respondents%20Merits%20Brief%20-%20FINAL.pdf","side":"res","n":24},{"k":"petitioner","label":"Brief of petitioners Federal Bureau of Investigation, et al.","date":"2021-07-30","url":"https://www.supremecourt.gov/DocketPDF/20/20-828/185459/20210730194532883_20-828tsUnitedStates.pdf","side":"pet","n":70},{"k":"respondent","label":"Brief of respondents Yassir Fazaga, et al.","date":"2021-09-21","url":"https://www.supremecourt.gov/DocketPDF/20/20-828/193269/20210921155749522_20-828%20FBI%20v%20Fazaga%20Brief%20for%20the%20Respondents.pdf","side":"res","n":72},{"k":"reply","label":"Reply of petitioners Federal Bureau of Investigation, et al.","date":"2021-10-21","url":"https://www.supremecourt.gov/DocketPDF/20/20-828/197203/20211021192253263_20-828rbUnited%20States.pdf","side":"pet","n":61}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/595us2r15_l537.pdf","tr":true,"items":[{"t":"case","label":"Abourezk v. Reagan","cite":"785 F.2d 1043","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/785/1043/","by":{"0":"23, 25"}},{"t":"case","label":"American-Arab Anti-Discrimination Committee v. Reno","cite":"70 F.3d 1045","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/70/1045/","by":{"0":"24"}},{"t":"case","label":"Association for Reduction of Violence v. Hall","cite":"734 F.2d 63","y":1984,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/734/63/","by":{"0":"31"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"ar":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"4","1":"passim","2":"11"}},{"t":"case","label":"Bonaparte v. Camden & Amboy Railroad Co.","cite":"3 F. Cas. 821","y":1830,"court":"C.C.D. N.J.","url":"https://www.courtlistener.com/c/F.%20Cas./3/821/","by":{"0":"28"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"sum":"Respondent brought suit in Federal District Court in Indiana on behalf of her deceased son's estate, alleging that her son while a prisoner in a federal prison in Indiana suffered personal injuries from which he died because petitioner prison officials violated, inter alia, his Eighth Amendment rights by failing to give him proper medical attention. Asserting jurisdiction under 28 U. S. C. § 1331 (a), respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"7, 10"}},{"t":"case","label":"Church of Lukumi Babalu Aye, Inc. v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"ar":3,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"City of Monterey v. Del Monte Dunes at Monterey, Ltd.","cite":"526 U.S. 687","y":1999,"id":"1998/97-1235","sc":1,"sum":"The Court held, in an opinion authored by Justice Anthony M. Kennedy, that property owners who file a Section 1983 civil rights suit seeking compensation for an alleged taking of their property can have a jury trial in some circumstances. \"[T]he disputed questions were whether the government had denied a constitutional right outside the bounds of its authority, and, if so, the extent of any resulting damages.\" Justice Kennedy then added: \"These were questions for the jury.\".","sumSrc":"Oyez","by":{"0":"27, 28","1":"passim"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"31","3":"64"}},{"t":"case","label":"Colgrove v. Battin","cite":"413 U.S. 149","y":1973,"id":"1972/71-1442","sc":1,"sum":"Local federal court rule providing that a jury for the trial of civil cases shall consist of six persons comports with the Seventh Amendment requirement and the coextensive statutory requirement of 28 U. S. C. § 2072 that the right of trial by jury be preserved in suits at common law, and is not inconsistent with Fed. Rule Civ. Proc. 48 that deals only with parties' stipulations regarding jury size. Pp. 151-164. 456 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Connecticut v. Doehr","cite":"501 U.S. 1","y":1991,"id":"1990/90-143","sc":1,"sum":"The judgment is affirmed. 898,F. 2d 852, affirmed. JUSTICE WHITE delivered the opinion of the Court with respect to Parts 1, 11, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"EEOC v. BDO USA, LLP","cite":"876 F.3d 690","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/876/690/","by":{"0":"31"}},{"t":"case","label":"El-Masri v. United States","cite":"479 F.3d 296","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/479/296/","by":{"0":"15","2":"5, 26, 45","3":"30, 32","4":"4, 19"}},{"t":"case","label":"Fazaga v. FBI","cite":"916 F.3d 1202","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/916/1202/","by":{"0":"7, 8, 9"}},{"t":"case","label":"Fidelity & Deposit Co. of Maryland v. United States","cite":"187 U.S. 315","y":1902,"id":"scdb/1902-024","sc":1,"sum":"I. This court has already sustained the power of the Supreme Court of the District of Columbia to adopt a rule providing that if the plaintiff or his agént shall file an affidavit in any action arising ex contractu setting out distinctly his cause of action, etc., and serve the defendant with copies thereof and of the declaration, he shall be entitled to judgment unless the defendant shall file, along with his plea, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Fuentes v. Shevin","cite":"407 U.S. 67","y":1972,"id":"1971/70-5039","sc":1,"sum":"Appellants, most of whom were purchasers of household goods under conditional sales contracts, challenge the constitutionality of prejudgment replevin provisions of Florida law (in No. 70-5039) and Pennsylvania law (in No. 70-5138). These provisions permit a private party, withouit a hearing or prior notice to the other party, to obtain a prejudgment writ of replevin through a summary process of ex parte application …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Galloway v. United States","cite":"319 U.S. 372","y":1943,"id":"scdb/1942-050","sc":1,"sum":"1. In this suit against the United States to recover benefits under a contract of war risk insurance, on account of alleged total and permanent disability resulting from insanity of the insured while the policy was in force, held that the evidence was insufficient to support a judgment for the plaintiff and the trial court properly granted the Government's motion for a directed verdict.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"General Dynamics Corp. v. United States","cite":"563 U.S. 478","y":2011,"id":"2010/09-1298","sc":1,"op":4,"sum":"Noting that the privilege exists to serve the “sometimes-compelling necessity of governmental secrecy” over “military, intelligence, and diplomatic” information.","sumSrc":"opinion","by":{"0":"6, 12, 14, 15, 16","2":"3, 4, 5, 25, 28","3":"passim","4":"19, 22"}},{"t":"case","label":"Granfinanciera, S.A. v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"sum":"The Court held that the Seventh Amendment protected the right to a trial by jury in all cases in which a legal right, as opposed to an equitable right, was at issue.","sumSrc":"Oyez","by":{"0":"13, 27","1":"12"}},{"t":"case","label":"Haines v. Liggett Group, Inc.","cite":"975 F.2d 81","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/975/81/","by":{"0":"31"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"op":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"21","3":"38"}},{"t":"case","label":"Joint Anti-Fascist Refugee Committee v. McGrath","cite":"341 U.S. 123","y":1951,"id":"scdb/1950-068","sc":1,"sum":"The judgments are reversed and the cases are remanded to the District Court with instructions to deny the motions that the complaints be dismissed for failure to state claims upon which relief could be granted. Pp. 124-125, 142. 85 U. S. App. D. C. 255, 177 F. 2d 79; 86 U. S. App. D. C. 287, 182 F. 2d 368, reversed. Opinion of BURTON, J. For the opinions of the Justices constituting the majority of the Court, see: …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Kasza v. Browner","cite":"133 F.3d 1159","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/1159/","by":{"0":"15","2":"34","4":"20"}},{"t":"case","label":"Lee v. Willey","cite":"789 F.3d 673","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/789/673/","by":{"0":"28"}},{"t":"case","label":"Ludwig v. Astrue","cite":"681 F.3d 1047","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/681/1047/","by":{"0":"23, 24"}},{"t":"case","label":"Page(s) Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"0":"13, 22"}},{"t":"case","label":"McNutt v. General Motors Acceptance Corp. of Indiana","cite":"298 U.S. 178","y":1936,"id":"scdb/1935-115","sc":1,"sum":"' Mr. Joseph W. Hutchinson, Assistant Attorney General of Indiana, and Mr. Leo M. Gardner, with whom Mr. Philip Lutz, Jr., Attorney General, was on the brief, for appellants.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Mohamed v. Jeppesen Dataplan, Inc.","cite":"614 F.3d 1070","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/614/1070/","by":{"0":"5, 6, 15","2":"5, 26, 27","3":"14, 15, 16, 30, 32","4":"3, 18, 19"}},{"t":"case","label":"Molerio v. FBI","cite":"749 F.2d 815","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/749/815/","ar":3,"by":{"0":"25, 26","3":"31, 32, 65","4":"20"}},{"t":"case","label":"Nurse v. United States","cite":"226 F.3d 996","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/226/996/","by":{"0":"27","1":"10"}},{"t":"case","label":"Philip Morris USA v. Williams","cite":"549 U.S. 346","y":2007,"id":"2006/05-1256","sc":1,"sum":"The Court ruled 5-4 that \"the Constitution's Due Process Clause forbids a State to use a punitive damages award to punish a defendant for injury that it inflicts upon nonparties.\" The opinion by Justice Stephen Breyer held that it would be unfair to allow courts to award punitive damages for harm done to \"strangers to the litigation,\" because defendants cannot defend themselves against such limitless and arbitrary charges.","sumSrc":"Oyez","by":{"0":"15, 22"}},{"t":"case","label":"Roviaro v. United States","cite":"353 U.S. 53","y":1957,"id":"1956/58","sc":1,"sum":"Held that Roviaro's interest in preparing his defense outweighed the public interest in protecting John Doe's identity.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Slocum v. New York Life Insurance Co.","cite":"228 U.S. 364","y":1913,"id":"scdb/1912-171","sc":1,"sum":"Where a life insurance policy plainly provides for payment of the stipulated premium within a specified period of grace after the due day and as plainly excludes any idea of partial payments distributed between the premium dates, the insured gains nothing by giving an agent a portion of the premium in the absence of authority given him by the company to accept it.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Small v. Camden County","cite":"728 F.3d 265","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/728/265/","by":{"0":"28"}},{"t":"case","label":"Tenenbaum v. Simonini","cite":"372 F.3d 776","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/372/776/","by":{"0":"15","2":"5, 26","3":"31","4":"19"}},{"t":"case","label":"Tenet v. Doe","cite":"544 U.S. 1","y":2005,"id":"2004/03-1395","sc":1,"op":2,"sum":"The Court held that Totten barred the Does' suit. Totten, the Court ruled, prohibited judicial review in any case where success depended on the existence of a secret espionage relationship with the government. To risk revealing that relationship would endanger the essence of a spy's contract with the government - secrecy.","sumSrc":"Oyez","by":{"0":"15, 21","3":"4, 25, 26","4":"19, 21, 22"}},{"t":"case","label":"Totten v. United States","cite":"92 U.S. 105","y":1876,"id":"scdb/1875-148","sc":1,"op":2,"ar":12,"sum":"Explaining that “the maintenance of any suit in a court of justice” is forbidden where continued litigation “would inevitably lead to the disclosure of ” state secrets.","sumSrc":"brief:4","by":{"0":"14, 15","2":"3, 5, 26","3":"passim","4":"19, 21"}},{"t":"case","label":"United States v. Abu-Jihaad","cite":"630 F.3d 102","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/630/102/","sum":"Upholding application to request for “disclosure of FISA materials” and for an adversarial “preliminary hearing” on the admissibility of the evidence.","sumSrc":"brief:1","by":{"0":"24","1":"16"}},{"t":"case","label":"United States v. Alvarez-Sanchez","cite":"511 U.S. 350","y":1994,"id":"1993/92-1812","sc":1,"sum":"The Court held that the provisions of the federal statute in question do not apply to suspects being held solely on state charges. The Court explained that no delay is said to occur until the suspect is arrested and detained for a federal crime. The six-hour period only begins to expire from the point of a suspect's federal arrest and charging.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"United States v. Aref","cite":"533 F.3d 72","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/533/72/","by":{"0":"30"}},{"t":"case","label":"Page(s) United States v. Belfield","cite":"692 F.2d 141","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/692/141/","sum":"Rejecting challenge to use of in camera, ex be imposed violates due process.","sumSrc":"brief:0","by":{"0":"24","1":"16","2":"37","3":"55, 56"}},{"t":"case","label":"United States v. Damrah","cite":"412 F.3d 618","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/412/618/","sum":"Upholding application to “motions to compel the production of FISA applications, orders, and related documents and to suppress FISA obtained evidence”.","sumSrc":"brief:1","by":{"0":"24","1":"16"}},{"t":"case","label":"United States v. James Daniel Good Real Property","cite":"510 U.S. 43","y":1993,"id":"1993/92-1180","sc":1,"sum":"Four and one-half years after police found drugs and drug paraphernalia in claimant Good's home and he pleaded guilty to promoting a harmful drug in violation of Hawaii law, the United States filed an in rem action in the Federal District Court, seeking forfeiture of his house and land, under 21 U. S. C. §881(a)(7), on the ground that the property had been used to commit or facilitate the commission of a federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"United States v. Mejia","cite":"448 F.3d 436","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/448/436/","by":{"0":"31"}},{"t":"case","label":"United States v. Nicholson","cite":"955 F. Supp. 588","y":1997,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./955/588/","by":{"0":"24","1":"16"}},{"t":"case","label":"United States v. Ott","cite":"827 F.2d 473","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/827/473/","by":{"0":"24","1":"16"}},{"t":"case","label":"United States v. Reynolds","cite":"345 U.S. 1","y":1953,"id":"1940-1955/345us1","sc":1,"op":5,"ar":15,"sum":"The court held that cause for privilege must be reasonably demonstrated. As a result, the government may withhold information for reasons of national security even when that information is vital to the plaintiff's case. On remand, the plaintiffs lost.","sumSrc":"Oyez","by":{"0":"6, 12, 14, 21","2":"passim","3":"passim","4":"9, 15, 19, 21"}},{"t":"case","label":"United States v. Sedaghaty","cite":"728 F.3d 885","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/728/885/","by":{"0":"30"}},{"t":"case","label":"United States v. Stewart","cite":"590 F.3d 93","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/590/93/","by":{"0":"31"}},{"t":"case","label":"Vining v. Runyon","cite":"99 F.3d 1056","y":1996,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/99/1056/","sum":"Holding that “the district court erred in using information obtained in its ex parte, in camera examination of [evidence] to judge the merits of [a] Title VII claim”.","sumSrc":"brief:0","by":{"0":"24"}},{"t":"case","label":"Ward v. United States Postal Service","cite":"634 F.3d 1274","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/634/1274/","by":{"0":"23"}},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"sum":"The Court held that, in situations where a federal action does not have a statute of limitations, the practice has been to adopt a local limitation as long as that limitation is not inconsistent with a federal law or policy.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"0":"3","1":"11","4":"16"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"3","1":"3"}},{"t":"usc","label":"50 U.S.C. § 1801","url":"https://www.law.cornell.edu/uscode/text/50/1801","subs":["(g)","(h)","(k)"],"stext":{"head":"§1801. Definitions","paras":[[0,"As used in this subchapter:"],[1,"(a) \"Foreign power\" means—"],[2,"(1) a foreign government or any component thereof, whether or not recognized by the United States;"],[2,"(2) a faction of a foreign nation or nations, not substantially composed of United States persons;"],[2,"(3) an entity that is openly acknowledged by a foreign government or governments to be directed and controlled by such foreign government or governments;"],[2,"(4) a group engaged in international terrorism or activities in preparation therefor;"],[2,"(5) a foreign-based political organization, not substantially composed of United States persons;"],[2,"(6) an entity that is directed and controlled by a foreign government or governments; or"],[2,"(7) an entity not substantially composed of United States persons that is engaged in the international proliferation of weapons of mass destruction."],[1,"(b) \"Agent of a foreign power\" means—"],[2,"(1) any person other than a United States person, who—"],[3,"(A) acts in the United States as an officer or employee of a foreign power, or as a member of a foreign power as defined in subsection (a)(4), irrespective of whether the person is inside the United States;"],[3,"(B) acts for or on behalf of a foreign power which engages in clandestine intelligence activities in the United States contrary to the interests of the United States, when the circumstances indicate that such person may engage in such activities, or when such person knowingly aids or abets any person in the conduct of such activities or knowingly conspires with any person to engage in such activities;"],[3,"(C) Omitted"],[3,"(D) engages in the international proliferation of weapons of mass destruction, or activities in preparation therefor; or"],[3,"(E) engages in the international proliferation of weapons of mass destruction, or activities in preparation therefor, for or on behalf of a foreign power, or knowingly aids or abets any person in the conduct of such proliferation or activities in preparation therefor, or knowingly conspires with any person to engage in such proliferation or activities in preparation therefor; or"],[2,"(2) any person who—"],[3,"(A) knowingly engages in clandestine intelligence gathering activities for or on behalf of a foreign power, which activities involve or may involve a violation of the criminal statutes of the United States;"],[3,"(B) pursuant to the direction of an intelligence service or network of a foreign power, knowingly engages in any other clandestine intelligence activities for or on behalf of such foreign power, which activities involve or are about to involve a violation of the criminal statutes of the United States;"],[3,"(C) knowingly engages in sabotage or international terrorism, or activities that are in preparation therefor, for or on behalf of a foreign power;"],[3,"(D) knowingly enters the United States under a false or fraudulent identity for or on behalf of a foreign power or, while in the United States, knowingly assumes a false or fraudulent identity for or on behalf of a foreign power; or"],[3,"(E) knowingly aids or abets any person in the conduct of activities described in subparagraph (A), (B), or (C) or knowingly conspires with any person to engage in activities described in subparagraph (A), (B), or (C)."],[1,"(c) \"International terrorism\" means activities that—"],[2,"(1) involve violent acts or acts dangerous to human life that are a violation of the criminal laws of the United States or of any State, or that would be a criminal violation if committed within the jurisdiction of the United States or any State;"],[2,"(2) appear to be intended—"],[3,"(A) to intimidate or coerce a civilian population;"],[3,"(B) to influence the policy of a government by intimidation or coercion; or"],[3,"(C) to affect the conduct of a government by assassination or kidnapping; and"],[2,"(3) occur totally outside the United States, or transcend national boundaries in terms of the means by which they are accomplished, the persons they appear intended to coerce or intimidate, or the locale in which their perpetrators operate or seek asylum."],[1,"(d) \"Sabotage\" means activities that involve a violation of chapter 105 of title 18, or that would involve such a violation if committed against the United States."],[1,"(e) \"Foreign intelligence information\" means—"],[2,"(1) information that relates to, and if concerning a United States person is necessary to, the ability of the United States to protect against—"],[3,"(A) actual or potential attack or other grave hostile acts of a foreign power or an agent of a foreign power;"],[3,"(B) sabotage, international terrorism, or the international proliferation of weapons of mass destruction by a foreign power or an agent of a foreign power;"],[3,"(C) clandestine intelligence activities by an intelligence service or network of a foreign power or by an agent of a foreign power; or"],[3,"(D) international production, distribution, or financing of illicit synthetic drugs, opioids, cocaine, or other drugs driving overdose deaths, or precursors of any aforementioned; or"],[2,"(2) information with respect to a foreign power or foreign territory that relates to, and if concerning a United States person is necessary to—"],[3,"(A) the national defense or the security of the United States; or"],[3,"(B) the conduct of the foreign affairs of the United States."],[1,"(f) \"Electronic surveillance\" means—"],[2,"(1) the acquisition by an electronic, mechanical, or other surveillance device of the contents of any wire or radio communication sent by or intended to be received by a particular, known United States person who is in the United States, if the contents are acquired by intentionally targeting that United States person, under circumstances in which a person has a reasonable expectation of privacy and a warrant would be required for law enforcement purposes;"],[2,"(2) the acquisition by an electronic, mechanical, or other surveillance device of the contents of any wire communication to or from a person in the United States, without the consent of any party thereto, if such acquisition occurs in the United States, but does not include the acquisition of those communications of computer trespassers that would be permissible under section 2511(2)(i) of title 18;"],[2,"(3) the intentional acquisition by an electronic, mechanical, or other surveillance device of the contents of any radio communication, under circumstances in which a person has a reasonable expectation of privacy and a warrant would be required for law enforcement purposes, and if both the sender and all intended recipients are located within the United States; or"],[2,"(4) the installation or use of an electronic, mechanical, or other surveillance device in the United States for monitoring to acquire information, other than from a wire or radio communication, under circumstances in which a person has a reasonable expectation of privacy and a warrant would be required for law enforcement purposes."],[1,"(g) \"Attorney General\" means the Attorney General of the United States (or Acting Attorney General), the Deputy Attorney General, or, upon the designation of the Attorney General, the Assistant Attorney General designated as the Assistant Attorney General for National Security under section 507A of title 28."],[1,"(h) \"Minimization procedures\", with respect to electronic surveillance, means—"],[2,"(1) specific procedures, which shall be adopted by the Attorney General, that are reasonably designed in light of the purpose and technique of the particular surveillance, to minimize the acquisition and retention, and prohibit the dissemination, of nonpublicly available information concerning unconsenting United States persons consistent with the need of the United States to obtain, produce, and disseminate foreign intelligence information;"],[2,"(2) procedures that require that nonpublicly available information, which is not foreign intelligence information, as defined in subsection (e)(1), shall not be disseminated in a manner that identifies any United States person, without such person's consent, unless such person's identity is necessary to understand foreign intelligence information or assess its importance;"],[2,"(3) notwithstanding paragraphs (1) and (2), procedures that allow for the retention and dissemination of information that is evidence of a crime which has been, is being, or is about to be committed and that is to be retained or disseminated for law enforcement purposes; and"],[2,"(4) notwithstanding paragraphs (1), (2), and (3), with respect to any electronic surveillance approved pursuant to section 1802(a) of this title, procedures that require that no contents of any communication to which a United States person is a party shall be disclosed, disseminated, or used for any purpose or retained for longer than 72 hours unless a court order under section 1805 of this title is obtained or unless the Attorney General determines that the information indicates a threat of death or serious bodily harm to any person."],[1,"(i) \"United States person\" means a citizen of the United States, an alien lawfully admitted for permanent residence (as defined in section 1101(a)(20) of title 8), an unincorporated association a substantial number of members of which are citizens of the United States or aliens lawfully admitted for permanent residence, or a corporation which is incorporated in the United States, but does not include a corporation or an association which is a foreign power, as defined in subsection (a)(1), (2), or (3)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1801?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1801. Definitions","tname":"War and National Defense","by":{"0":"18","1":"passim","2":"6, 6, 36, 7, 7","3":"passim","4":"1"}},{"t":"case","label":"Curtis v. Loether","cite":"415 U.S. 189","y":1974,"id":"1973/72-1035","sc":1,"sum":"The Seventh Amendment of the Constitution entitles either party to demand a jury trial in an action for damages in the federal courts under § 812 of the Civil Rights Act of 1968, which authorizes privateplaintiffs to bring civil actions to redress violations of the Act's fair housing provisions. Pp. 191-198. 467 F. 2d 1110, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10, 13"}},{"t":"case","label":"Edmonson v. Leesville Concrete Co.","cite":"500 U.S. 614","y":1991,"id":"1990/89-7743","sc":1,"sum":"A private litigant in a civil case may not use peremptory challenges to exclude jurors on account of race.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10"}},{"t":"case","label":"Feltner v. Columbia Pictures Television, Inc.","cite":"523 U.S. 340","y":1998,"id":"1997/96-1768","sc":1,"sum":"The Court held that, despite section 504(c) of the Copyright Act's silence, the Seventh Amendment provides the right to a jury trial, which includes a right to a jury determination of the amount of statutory damages.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Hartman v. Moore","cite":"547 U.S. 250","y":2006,"id":"2005/04-1495","sc":1,"sum":"The Court ruled in favor of the postal inspectors, overruling the Court of Appeals. The opinion by Justice David Souter held that plaintiffs alleging retaliatory prosecution must prove that the law enforcement agents lacked probable cause. Probable cause, the Court ruled, is a crucial component of the \"chain of causation\" needed to evaluate retaliatory prosecution charges.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Hernandez v. Mesa","cite":"140 S. Ct. 735","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Lytle v. Household Mfg., Inc.","cite":"494 U.S. 545","y":1990,"id":"1989/88-334","sc":1,"sum":"Petitioner Lytle, an Afro-American, filed an action under both Title VII of the Civil Rights Act of 1964 and 42 U. S. C. § 1981, alleging that respondent Schwitzer Turbochargers had terminated his employment because of his race and had retaliated against him for filing a charge with the Equal Employment Opportunity Commission by subsequently providing inadequate references to prospective employers. He requested a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"8, 14, 15","3":"58"}},{"t":"case","label":"Ortiz v. Fibreboard Corp.","cite":"527 U.S. 815","y":1999,"id":"1998/97-1704","sc":1,"sum":"The Court held that \"applicants for contested certification [of a mandatory settlement class on a limited fund theory under Rule 23(b)(1)(B)] must show that the fund is limited by more than the agreement of the parties, and has been allocated to claimants belonging within the class by a process addressing any conflicting interests of class members.\" \"The record on which the District Court rested its certification of the class for the purpose of the global settlement did not support the essential premises of mandatory limited fund actions.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"1":"10"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"11, 12"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"1":"14"}},{"t":"case","label":"Al-Haramain Islamic Found., Inc. v. Obama","cite":"705 F.3d 845","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/845/","by":{"2":"7"}},{"t":"case","label":"American Ins. Ass’n v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"sum":"The Court held that California's HVIRA interferes with the president's ability to conduct the nation's foreign policy and is therefore preempted. The Court reasoned that an exercise of state power that concerns foreign relations must yield to the Federal Government's policy or that generally there is executive authority to decide what policy should be implemented.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Bareford v. General Dynamics Corp.","cite":"973 F.2d 1138","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/973/1138/","by":{"2":"27","4":"20"}},{"t":"case","label":"Black v. United States","cite":"62 F.3d 1115","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/62/1115/","by":{"2":"5, 26","3":"31","4":"20"}},{"t":"case","label":"Chicago & S. Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"2":"45","3":"60"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":1,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"2":"6, 34, 38","3":"60"}},{"t":"case","label":"Department of the Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"sum":"In an appeal pursuant to § 7513, the Board does not have authority to review the substance of an underlying security-clearance determination in the course of reviewing an adverse action.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20, 45, 46","3":"59, 60","4":"13, 14"}},{"t":"case","label":"Fitzgerald v. Penthouse Int’l, Ltd.","cite":"776 F.2d 1236","y":1985,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/776/1236/","by":{"2":"27, 37","4":"20"}},{"t":"case","label":"Franchise Tax Bd. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"45"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Halkin v. Helms","cite":"598 F.2d 1","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/598/1/","ar":1,"by":{"2":"43"}},{"t":"case","label":"New York Times Co. v. United States","cite":"403 U.S. 713","y":1971,"id":"1970/1873","sc":1,"sum":"The Court found that the use of \"prior restraint\" by President Nixon on a New York Times article about activities in Vietnam was an unconstitutional violation of the First Amendment.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Norfolk Redevelopment & Hous. Auth. v. Chesapeake & Potomac Tel. Co.","cite":"464 U.S. 30","y":1983,"id":"1983/81-2332","sc":1,"op":1,"sum":"C&P is not a \"displaced person\" within the meaning of the Act. The Act did not change the long-established common-law principle that a utility forced to relocate from a public right-of-way must do so at its own expense. An analysis of the Act-the purposes of which were to ensure that persons displaced by federal and federally funded programs would receive uniform treatment and would not suffer disproportionate …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Public Citizen v. United States Dep’t of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42","3":"63"}},{"t":"case","label":"Sale v. Haitian Ctrs. Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"sum":"And, it found that both section 243(h) and Article 33 are silent regarding extraterritorial application. In fact, the language of both suggests that only individuals who have already arrived on United States soil are protected, and their use throughout history confirms this interpretation. Thus, the judgment of the Court of Appeals is reversed.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Sterling v. Tenet","cite":"416 F.3d 338","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/416/338/","sum":"Recognizing that in camera consideration of state secrets is “play[ing] with fire”.","sumSrc":"brief:2","by":{"2":"4, 28, 34, 38","4":"19"}},{"t":"case","label":"Sturgeon v. Frost","cite":"577 U.S. 424","y":2016,"id":"2015/14-1209","sc":1,"sum":"The Court held that the Alaska National Interest Lands Conservation Act of 1980 did not allow the National Park Service to regulate all land physically within the boundaries of the National Park System in Alaska.","sumSrc":"Oyez","by":{"2":"29","4":"5"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 187","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/187/","by":{"2":"3","3":"62"}},{"t":"case","label":"United States v. Mandujano","cite":"425 U.S. 564","y":1976,"id":"1975/74-754","sc":1,"sum":"The judgment is reversed and the case is remanded. Pp. 571-584; 584-609; 609. 496 F. 2d 1050, reversed and remanded. THE CHIEF JUSTICE, joined by MR. JUSTICE WHITE, MR. JUSTICE POWELL, and MR. JUSTICE REHNQUIST, concluded that Miranda warnings need not be given to a grand jury witness who is called to testify about criminal activities in which he may have been personally involved, and that therefore the failure to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"ar":2,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"2":"3, 20, 43, 45","3":"53, 59, 62","4":"13, 14"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Washington State Dep’t of Soc. & Health Servs. v. Guardianship Estate of Keffeler","cite":"537 U.S. 371","y":2003,"id":"2002/01-1420","sc":1,"sum":"The Court held that the state's use of the Social Security benefits to reimburse itself does not violate the Social Security Act's anti-attachment provision.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"31, 35"}},{"t":"case","label":"Zuckerbraun v. General Dynamics Corp.","cite":"935 F.2d 544","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/935/544/","by":{"2":"27","4":"20"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"34"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"2":"11"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"2":"11"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"11","4":"16"}},{"t":"usc","label":"28 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/28/1326","subs":["(b)"],"by":{"2":"11"}},{"t":"usc","label":"50 U.S.C. § 1803","url":"https://www.law.cornell.edu/uscode/text/50/1803","subs":["(a)","(g)"],"stext":{"head":"§1803. Designation of judges","paras":[[0,"(a) Court to hear applications and grant orders; record of denial; transmittal to court of review"],[0,"(1) The Chief Justice of the United States shall publicly designate 11 district court judges from at least seven of the United States judicial circuits of whom no fewer than 3 shall reside within 20 miles of the District of Columbia who shall constitute a court which shall have jurisdiction to hear applications for and grant orders approving electronic surveillance anywhere within the United States under the procedures set forth in this chapter, except that no judge designated under this subsection (except when sitting en banc under paragraph (2)) shall hear the same application for electronic surveillance under this chapter which has been denied previously by another judge designated under this subsection. If any judge so designated denies an application for an order authorizing electronic surveillance under this chapter, such judge shall provide immediately for the record a written statement of each reason for his decision and, on motion of the United States, the record shall be transmitted, under seal, to the court of review established in subsection (b)."],[0,"(2)(A) The court established under this subsection may, on its own initiative, or upon the request of the Government in any proceeding or a party under section 1861(f) 1 of this title or paragraph (4) or (5) of section 1881a(i) of this title, hold a hearing or rehearing, en banc, when ordered by a majority of the judges that constitute such court upon a determination that—"],[1,"(i) en banc consideration is necessary to secure or maintain uniformity of the court's decisions; or"],[1,"(ii) the proceeding involves a question of exceptional importance."],[0,"(B) Any authority granted by this chapter to a judge of the court established under this subsection may be exercised by the court en banc. When exercising such authority, the court en banc shall comply with any requirements of this chapter on the exercise of such authority."],[0,"(C) For purposes of this paragraph, the court en banc shall consist of all judges who constitute the court established under this subsection."],[0,"(b) Court of review; record, transmittal to Supreme Court"],[0,"The Chief Justice shall publicly designate three judges, one of whom shall be publicly designated as the presiding judge, from the United States district courts or courts of appeals who together shall comprise a court of review which shall have jurisdiction to review the denial of any application made under this chapter. If such court determines that the application was properly denied, the court shall provide for the record a written statement of each reason for its decision and, on petition of the United States for a writ of certiorari, the record shall be transmitted under seal to the Supreme Court, which shall have jurisdiction to review such decision."],[0,"(c) Expeditious conduct of proceedings; security measures for maintenance of records"],[0,"Proceedings under this chapter shall be conducted as expeditiously as possible, and hearings shall be transcribed. The record of proceedings under this chapter, including applications made, transcriptions of hearings, and orders granted, shall be maintained under security measures established by the Chief Justice in consultation with the Attorney General and the Director of National Intelligence. Transcriptions and any related records, including testimony and affidavits, shall be stored in a file associated with the relevant application or order."],[0,"(d) Tenure"],[0,"Each judge designated under this section shall so serve for a maximum of seven years and shall not be eligible for redesignation, except that the judges first designated under subsection (a) shall be designated for terms of from one to seven years so that one term expires each year, and that judges first designated under subsection (b) shall be designated for terms of three, five, and seven years."],[0,"(e) Jurisdiction and procedures for review of petitions"],[0,"(1) Three judges designated under subsection (a) who reside within 20 miles of the District of Columbia, or, if all of such judges are unavailable, other judges of the court established under subsection (a) as may be designated by the presiding judge of such court, shall comprise a petition review pool which shall have jurisdiction to review petitions filed pursuant to section 1861(f)(1) 1 or 1881a(i)(4) of this title."],[0,"(2) Not later than 60 days after March 9, 2006, the court established under subsection (a) shall adopt and, consistent with the protection of national security, publish procedures for the review of petitions filed pursuant to section 1861(f)(1) 1 or 1881a(i)(4) of this title by the panel established under paragraph (1). Such procedures shall provide that review of a petition shall be conducted in camera and shall also provide for the designation of an acting presiding judge."],[0,"(f) Stay of order"],[0,"(1) A judge of the court established under subsection (a), the court established under subsection (b) or a judge of that court, or the Supreme Court of the United States or a justice of that court, may, in accordance with the rules of their respective courts, enter a stay of an order or an order modifying an order of the court established under subsection (a) or the court established under subsection (b) entered under any subchapter of this chapter, while the court established under subsection (a) conducts a rehearing, while an appeal is pending to the court established under subsection (b), or while a petition of certiorari is pending in the Supreme Court of the United States, or during the pendency of any review by that court."],[0,"(2) The authority described in paragraph (1) shall apply to an order entered under any provision of this chapter."],[0,"(g) Establishment and transmittal of rules and procedures"],[0,"(1) The courts established pursuant to subsections (a) and (b) may establish such rules and procedures, and take such actions, as are reasonably necessary to administer their responsibilities under this chapter."],[0,"(2) The rules and procedures established under paragraph (1), and any modifications of such rules and procedures, shall be recorded, and shall be transmitted to the following:"],[1,"(A) All of the judges on the court established pursuant to subsection (a)."],[1,"(B) All of the judges on the court of review established pursuant to subsection (b)."],[1,"(C) The Chief Justice of the United States."],[1,"(D) The Committee on the Judiciary of the Senate."],[1,"(E) The Select Committee on Intelligence of the Senate."],[1,"(F) The Committee on the Judiciary of the House of Representatives."],[1,"(G) The Permanent Select Committee on Intelligence of the House of Representatives."],[0,"(3) The transmissions required by paragraph (2) shall be submitted in unclassified form, but may include a classified annex."],[0,"(h) Compliance with orders, rules, and procedures"],[0,"Nothing in this chapter shall be construed to reduce or contravene the inherent authority of a court established under this section to determine or enforce compliance with an order or a rule of such court or with a procedure approved by such court."],[0,"(i) Amicus curiae"],[0,"(1) Designation"],[1,"The presiding judges of the courts established under subsections (a) and (b) shall, not later than 180 days after June 2, 2015, jointly designate not fewer than 5 individuals to be eligible to serve as amicus curiae, who shall serve pursuant to rules the presiding judges may establish. In designating such individuals, the presiding judges may consider individuals recommended by any source, including members of the Privacy and Civil Liberties Oversight Board, the judges determine appropriate."],[0,"(2) Authorization"],[0,"(A) In general"],[2,"A court established under subsection (a) or (b), consistent with the requirement of subsection (c) and any other statutory requirement that the court act expeditiously or within a stated time—"],[3,"(i) shall appoint one or more individuals who have been designated under paragraph (1) to serve as amicus curiae to assist such court in the consideration of any application for an order or review that, in the opinion of the court, presents a novel or significant interpretation of the law, unless the court issues a finding that such appointment is not appropriate;"],[3,"(ii) may appoint one or more individuals or organizations to serve as amicus curiae, including to provide technical expertise, in any instance as such court deems appropriate or, upon motion, permit an individual or organization leave to file an amicus curiae brief; and"],[3,"(iii) shall appoint one or more individuals who have been designated under paragraph (1) to serve as amicus curiae to assist such court in the consideration of any certification or procedures submitted for review pursuant to section 1881a of this title, including any amendments to such certifications or procedures, if the court established under subsection (a) has not appointed an individual under clause (i) or (ii), unless the court issues a finding that such appointment is not appropriate or is likely to result in undue delay."],[0,"(B) Expertise"],[2,"In appointing one or more individuals under subparagraph (A)(iii), the court shall, to the maximum extent practicable, appoint an individual who possesses expertise in both privacy and civil liberties and intelligence collection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1803?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1803. Designation of judges","tname":"War and National Defense","by":{"2":"6, 6, 33","3":"60","4":"14"}},{"t":"usc","label":"50 U.S.C. § 1804","url":"https://www.law.cornell.edu/uscode/text/50/1804","subs":["(a)"],"by":{"2":"6"}},{"t":"usc","label":"50 U.S.C. § 1805","url":"https://www.law.cornell.edu/uscode/text/50/1805","subs":["(a)","(a)(2)","(a)(3)","(c)(2)(A)"],"by":{"2":"6, 7, 6, 7, 7"}},{"t":"usc","label":"50 U.S.C. § 1806","url":"https://www.law.cornell.edu/uscode/text/50/1806","subs":["(a)","(c)","(d)","(e)","(g)","(f)","(h)"],"stext":{"head":"§1806. Use of information","paras":[[0,"(a) Compliance with minimization procedures; privileged communications; lawful purposes"],[0,"Information acquired from an electronic surveillance conducted pursuant to this subchapter concerning any United States person may be used and disclosed by Federal officers and employees without the consent of the United States person only in accordance with the minimization procedures required by this subchapter. No otherwise privileged communication obtained in accordance with, or in violation of, the provisions of this subchapter shall lose its privileged character. No information acquired from an electronic surveillance pursuant to this subchapter may be used or disclosed by Federal officers or employees except for lawful purposes."],[0,"(b) Statement for disclosure"],[0,"No information acquired pursuant to this subchapter shall be disclosed for law enforcement purposes unless such disclosure is accompanied by a statement that such information, or any information derived therefrom, may only be used in a criminal proceeding with the advance authorization of the Attorney General."],[0,"(c) Notification by United States"],[0,"Whenever the Government intends to enter into evidence or otherwise use or disclose in any trial, hearing, or other proceeding in or before any court, department, officer, agency, regulatory body, or other authority of the United States, against an aggrieved person, any information obtained or derived from an electronic surveillance of that aggrieved person pursuant to the authority of this subchapter, the Government shall, prior to the trial, hearing, or other proceeding or at a reasonable time prior to an effort to so disclose or so use that information or submit it in evidence, notify the aggrieved person and the court or other authority in which the information is to be disclosed or used that the Government intends to so disclose or so use such information."],[0,"(d) Notification by States or political subdivisions"],[0,"Whenever any State or political subdivision thereof intends to enter into evidence or otherwise use or disclose in any trial, hearing, or other proceeding in or before any court, department, officer, agency, regulatory body, or other authority of a State or a political subdivision thereof, against an aggrieved person any information obtained or derived from an electronic surveillance of that aggrieved person pursuant to the authority of this subchapter, the State or political subdivision thereof shall notify the aggrieved person, the court or other authority in which the information is to be disclosed or used, and the Attorney General that the State or political subdivision thereof intends to so disclose or so use such information."],[0,"(e) Motion to suppress"],[0,"Any person against whom evidence obtained or derived from an electronic surveillance to which he is an aggrieved person is to be, or has been, introduced or otherwise used or disclosed in any trial, hearing, or other proceeding in or before any court, department, officer, agency, regulatory body, or other authority of the United States, a State, or a political subdivision thereof, may move to suppress the evidence obtained or derived from such electronic surveillance on the grounds that—"],[1,"(1) the information was unlawfully acquired; or"],[1,"(2) the surveillance was not made in conformity with an order of authorization or approval."],[0,"Such a motion shall be made before the trial, hearing, or other proceeding unless there was no opportunity to make such a motion or the person was not aware of the grounds of the motion."],[0,"(f) In camera and ex parte review by district court"],[0,"Whenever a court or other authority is notified pursuant to subsection (c) or (d), or whenever a motion is made pursuant to subsection (e), or whenever any motion or request is made by an aggrieved person pursuant to any other statute or rule of the United States or any State before any court or other authority of the United States or any State to discover or obtain applications or orders or other materials relating to electronic surveillance or to discover, obtain, or suppress evidence or information obtained or derived from electronic surveillance under this chapter, the United States district court or, where the motion is made before another authority, the United States district court in the same district as the authority, shall, notwithstanding any other law, if the Attorney General files an affidavit under oath that disclosure or an adversary hearing would harm the national security of the United States, review in camera and ex parte the application, order, and such other materials relating to the surveillance as may be necessary to determine whether the surveillance of the aggrieved person was lawfully authorized and conducted. In making this determination, the court may disclose to the aggrieved person, under appropriate security procedures and protective orders, portions of the application, order, or other materials relating to the surveillance only where such disclosure is necessary to make an accurate determination of the legality of the surveillance."],[0,"(g) Suppression of evidence; denial of motion"],[0,"If the United States district court pursuant to subsection (f) determines that the surveillance was not lawfully authorized or conducted, it shall, in accordance with the requirements of law, suppress the evidence which was unlawfully obtained or derived from electronic surveillance of the aggrieved person or otherwise grant the motion of the aggrieved person. If the court determines that the surveillance was lawfully authorized and conducted, it shall deny the motion of the aggrieved person except to the extent that due process requires discovery or disclosure."],[0,"(h) Finality of orders"],[0,"Orders granting motions or requests under subsection (g), decisions under this section that electronic surveillance was not lawfully authorized or conducted, and orders of the United States district court requiring review or granting disclosure of applications, orders, or other materials relating to a surveillance shall be final orders and binding upon all courts of the United States and the several States except a United States court of appeals and the Supreme Court."],[0,"(i) Destruction of unintentionally acquired information"],[0,"In circumstances involving the unintentional acquisition by an electronic, mechanical, or other surveillance device of the contents of any communication, under circumstances in which a person has a reasonable expectation of privacy and a warrant would be required for law enforcement purposes, and if both the sender and all intended recipients are located within the United States, such contents shall be destroyed upon recognition, unless the Attorney General determines that the contents indicate a threat of death or serious bodily harm to any person."],[0,"(j) Notification of emergency employment of electronic surveillance; contents; postponement, suspension or elimination"],[0,"If an emergency employment of electronic surveillance is authorized under subsection (e) or (f) of section 1805 of this title and a subsequent order approving the surveillance is not obtained, the judge shall cause to be served on any United States person named in the application and on such other United States persons subject to electronic surveillance as the judge may determine in his discretion it is in the interest of justice to serve, notice of—"],[1,"(1) the fact of the application;"],[1,"(2) the period of the surveillance; and"],[1,"(3) the fact that during the period information was or was not obtained."],[0,"On an ex parte showing of good cause to the judge the serving of the notice required by this subsection may be postponed or suspended for a period not to exceed ninety days. Thereafter, on a further ex parte showing of good cause, the court shall forego ordering the serving of the notice required under this subsection."],[0,"(k) Coordination with law enforcement on national security matters"],[0,"(1) Federal officers who conduct electronic surveillance to acquire foreign intelligence information under this subchapter may consult with Federal law enforcement officers or law enforcement personnel of a State or political subdivision of a State (including the chief executive officer of that State or political subdivision who has the authority to appoint or direct the chief law enforcement officer of that State or political subdivision) to coordinate efforts to investigate or protect against—"],[1,"(A) actual or potential attack or other grave hostile acts of a foreign power or an agent of a foreign power;"],[1,"(B) sabotage, international terrorism, or the international proliferation of weapons of mass destruction by a foreign power or an agent of a foreign power; or"],[1,"(C) clandestine intelligence activities by an intelligence service or network of a foreign power or by an agent of a foreign power."],[0,"(2) Coordination authorized under paragraph (1) shall not preclude the certification required by section 1804(a)(7)(B) 1 of this title or the entry of an order under section 1805 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1806?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":3,"head":"§1806. Use of information","tname":"War and National Defense","by":{"2":"passim, 22, passim, passim, 8, 18, 22, 24, 30, 31, passim, passim","3":"passim, passim, 45, passim, passim, 44","4":"5, 3, 4, 4, passim, 5, 16"}},{"t":"usc","label":"50 U.S.C. § 1809","url":"https://www.law.cornell.edu/uscode/text/50/1809","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§1809. Criminal sanctions","paras":[[0,"(a) Prohibited activities"],[0,"A person is guilty of an offense if he—"],[1,"(1) intentionally engages in electronic surveillance under color of law except as authorized by this chapter, chapter 119, 121, or 206 of title 18, or any express statutory authorization that is an additional exclusive means for conducting electronic surveillance under section 1812 of this title;"],[1,"(2) intentionally discloses or uses information obtained under color of law by electronic surveillance, knowing or having reason to know that the information was obtained through electronic surveillance not authorized by this chapter, chapter 119, 121, or 206 of title 18, or any express statutory authorization that is an additional exclusive means for conducting electronic surveillance under section 1812 of this title; or"],[1,"(3) knowingly and willfully communicates, furnishes, transmits, or otherwise makes available to an unauthorized person, or publishes, or uses in any manner prejudicial to the safety or interest of the United States or for the benefit of any foreign government to the detriment of the United States an application, in whole or in part, for an order for electronic surveillance under this chapter."],[0,"(b) Defense"],[0,"It is a defense to a prosecution under paragraph (1) or (2) of subsection (a) that the defendant was a law enforcement or investigative officer engaged in the course of his official duties and the electronic surveillance was authorized by and conducted pursuant to a search warrant or court order of a court of competent jurisdiction."],[0,"(c) Penalty"],[0,"A person guilty of an offense in this section shall be fined under title 18, imprisoned for not more than 10 years, or both."],[0,"(d) Federal jurisdiction"],[0,"There is Federal jurisdiction over an offense under this section if the person committing the offense was an officer or employee of the United States at the time the offense was committed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1809?type=usc&year=mostrecent&link-type=html"},"head":"§1809. Criminal sanctions","tname":"War and National Defense","by":{"2":"6, 7","3":"7, 50"}},{"t":"usc","label":"50 U.S.C. § 1810","url":"https://www.law.cornell.edu/uscode/text/50/1810","subs":["(a)"],"stext":{"head":"§1810. Civil liability","paras":[[0,"An aggrieved person, other than a foreign power or an agent of a foreign power, as defined in section 1801(a) or (b)(1)(A) of this title, respectively, who has been subjected to an electronic surveillance or about whom information obtained by electronic surveillance of such person has been disclosed or used in violation of section 1809 of this title shall have a cause of action against any person who committed such violation and shall be entitled to recover—"],[1,"(a) actual damages, but not less than liquidated damages equal to the greater of—"],[2,"(1) if the aggrieved person is a United States person, $10,000 or $1,000 per day for each day of violation; or"],[2,"(2) for any other aggrieved person, $1,000 or $100 per day for each day of violation;"],[1,"(b) punitive damages; and"],[1,"(c) reasonable attorney's fees and other investigation and litigation costs reasonably incurred."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1810?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1810. Civil liability","tname":"War and National Defense","by":{"2":"7, 11, 12, 33, 34, 41, 33","3":"passim","4":"8, 9"}},{"t":"usc","label":"50 U.S.C. § 1812","url":"https://www.law.cornell.edu/uscode/text/50/1812","subs":["(a)"],"stext":{"head":"§1812. Statement of exclusive means by which electronic surveillance and interception of certain communications may be conducted","paras":[[0,"(a) Except as provided in subsection (b), the procedures of chapters 119, 121, and 206 of title 18 and this chapter shall be the exclusive means by which electronic surveillance and the interception of domestic wire, oral, or electronic communications may be conducted."],[0,"(b) Only an express statutory authorization for electronic surveillance or the interception of domestic wire, oral, or electronic communications, other than as an amendment to this chapter or chapters 119, 121, or 206 of title 18 shall constitute an additional exclusive means for the purpose of subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1812?type=usc&year=mostrecent&link-type=html"},"head":"§1812. Statement of exclusive means by which electronic surveillance and interception of certain communications may be conducted","tname":"War and National Defense","by":{"2":"41","3":"50"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","stext":{"head":"§552a. Records maintained on individuals","paras":[[0,"(a) Definitions.—For purposes of this section—"],[1,"(1) the term \"agency\" means agency as defined in section 552(e) 1 of this title;"],[1,"(2) the term \"individual\" means a citizen of the United States or an alien lawfully admitted for permanent residence;"],[1,"(3) the term \"maintain\" includes maintain, collect, use, or disseminate;"],[1,"(4) the term \"record\" means any item, collection, or grouping of information about an individual that is maintained by an agency, including, but not limited to, his education, financial transactions, medical history, and criminal or employment history and that contains his name, or the identifying number, symbol, or other identifying particular assigned to the individual, such as a finger or voice print or a photograph;"],[1,"(5) the term \"system of records\" means a group of any records under the control of any agency from which information is retrieved by the name of the individual or by some identifying number, symbol, or other identifying particular assigned to the individual;"],[1,"(6) the term \"statistical record\" means a record in a system of records maintained for statistical research or reporting purposes only and not used in whole or in part in making any determination about an identifiable individual, except as provided by section 8 of title 13;"],[1,"(7) the term \"routine use\" means, with respect to the disclosure of a record, the use of such record for a purpose which is compatible with the purpose for which it was collected;"],[1,"(8) the term \"matching program\"—"],[2,"(A) means any computerized comparison of—"],[3,"(i) two or more automated systems of records or a system of records with non-Federal records for the purpose of—"],[4,"(I) establishing or verifying the eligibility of, or continuing compliance with statutory and regulatory requirements by, applicants for, recipients or beneficiaries of, participants in, or providers of services with respect to, cash or in-kind assistance or payments under Federal benefit programs, or"],[4,"(II) recouping payments or delinquent debts under such Federal benefit programs, or"],[3,"(ii) two or more automated Federal personnel or payroll systems of records or a system of Federal personnel or payroll records with non-Federal records,"],[2,"(B) but does not include—"],[3,"(i) matches performed to produce aggregate statistical data without any personal identifiers;"],[3,"(ii) matches performed to support any research or statistical project, the specific data of which may not be used to make decisions concerning the rights, benefits, or privileges of specific individuals;"],[3,"(iii) matches performed, by an agency (or component thereof) which performs as its principal function any activity pertaining to the enforcement of criminal laws, subsequent to the initiation of a specific criminal or civil law enforcement investigation of a named person or persons for the purpose of gathering evidence against such person or persons;"],[3,"(iv) matches of tax information (I) pursuant to section 6103(d) of the Internal Revenue Code of 1986, (II) for purposes of tax administration as defined in section 6103(b)(4) of such Code, (III) for the purpose of intercepting a tax refund due an individual under authority granted by section 404(e), 464, or 1137 of the Social Security Act; or (IV) for the purpose of intercepting a tax refund due an individual under any other tax refund intercept program authorized by statute which has been determined by the Director of the Office of Management and Budget to contain verification, notice, and hearing requirements that are substantially similar to the procedures in section 1137 of the Social Security Act;"],[3,"(v) matches—"],[4,"(I) using records predominantly relating to Federal personnel, that are performed for routine administrative purposes (subject to guidance provided by the Director of the Office of Management and Budget pursuant to subsection (v)); or"],[4,"(II) conducted by an agency using only records from systems of records maintained by that agency;"],[0,"if the purpose of the match is not to take any adverse financial, personnel, disciplinary, or other adverse action against Federal personnel;"],[3,"(vi) matches performed for foreign counterintelligence purposes or to produce background checks for security clearances of Federal personnel or Federal contractor personnel;"],[3,"(vii) matches performed incident to a levy described in section 6103(k)(8) of the Internal Revenue Code of 1986;"],[3,"(viii) matches performed pursuant to section 202(x)(3) or 1611(e)(1) of the Social Security Act (42 U.S.C. 402(x)(3), 1382(e)(1));"],[3,"(ix) matches performed by the Secretary of Health and Human Services or the Inspector General of the Department of Health and Human Services with respect to potential fraud, waste, and abuse, including matches of a system of records with non-Federal records; or"],[3,"(x) matches performed pursuant to section 3(d)(4) of the Achieving a Better Life Experience Act of 2014; 1"],[1,"(9) the term \"recipient agency\" means any agency, or contractor thereof, receiving records contained in a system of records from a source agency for use in a matching program;"],[1,"(10) the term \"non-Federal agency\" means any State or local government, or agency thereof, which receives records contained in a system of records from a source agency for use in a matching program;"],[1,"(11) the term \"source agency\" means any agency which discloses records contained in a system of records to be used in a matching program, or any State or local government, or agency thereof, which discloses records to be used in a matching program;"],[1,"(12) the term \"Federal benefit program\" means any program administered or funded by the Federal Government, or by any agent or State on behalf of the Federal Government, providing cash or in-kind assistance in the form of payments, grants, loans, or loan guarantees to individuals; and"],[1,"(13) the term \"Federal personnel\" means officers and employees of the Government of the United States, members of the uniformed services (including members of the Reserve Components), individuals entitled to receive immediate or deferred retirement benefits under any retirement program of the Government of the United States (including survivor benefits)."],[0,"(b) Conditions of Disclosure.—No agency shall disclose any record which is contained in a system of records by any means of communication to any person, or to another agency, except pursuant to a written request by, or with the prior written consent of, the individual to whom the record pertains, unless disclosure of the record would be—"],[1,"(1) to those officers and employees of the agency which maintains the record who have a need for the record in the performance of their duties;"],[1,"(2) required under section 552 of this title;"],[1,"(3) for a routine use as defined in subsection (a)(7) of this section and described under subsection (e)(4)(D) of this section;"],[1,"(4) to the Bureau of the Census for purposes of planning or carrying out a census or survey or related activity pursuant to the provisions of title 13;"],[1,"(5) to a recipient who has provided the agency with advance adequate written assurance that the record will be used solely as a statistical research or reporting record, and the record is to be transferred in a form that is not individually identifiable;"],[1,"(6) to the National Archives and Records Administration as a record which has sufficient historical or other value to warrant its continued preservation by the United States Government, or for evaluation by the Archivist of the United States or the designee of the Archivist to determine whether the record has such value;"],[1,"(7) to another agency or to an instrumentality of any governmental jurisdiction within or under the control of the United States for a civil or criminal law enforcement activity if the activity is authorized by law, and if the head of the agency or instrumentality has made a written request to the agency which maintains the record specifying the particular portion desired and the law enforcement activity for which the record is sought;"],[1,"(8) to a person pursuant to a showing of compelling circumstances affecting the health or safety of an individual if upon such disclosure notification is transmitted to the last known address of such individual;"],[1,"(9) to either House of Congress, or, to the extent of matter within its jurisdiction, any committee or subcommittee thereof, any joint committee of Congress or subcommittee of any such joint committee;"],[1,"(10) to the Comptroller General, or any of his authorized representatives, in the course of the performance of the duties of the Government Accountability Office;"],[1,"(11) to the Director of the Congressional Budget Office, or any authorized representative of the Director, in the course of performance of the duties of the Congressional Budget Office;"],[1,"(12) pursuant to the order of a court of competent jurisdiction; or"],[1,"(13) to a consumer reporting agency in accordance with section 3711(e) of title 31."],[0,"(c) Accounting of Certain Disclosures.—Each agency, with respect to each system of records under its control, shall—"],[1,"(1) except for disclosures made under subsections (b)(1) or (b)(2) of this section, keep an accurate accounting of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§552a. Records maintained on individuals","tname":"Government Organization and Employees","by":{"2":"11"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","stext":{"head":"§2000bb. Congressional findings and declaration of purposes","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) the framers of the Constitution, recognizing free exercise of religion as an unalienable right, secured its protection in the First Amendment to the Constitution;"],[1,"(2) laws \"neutral\" toward religion may burden religious exercise as surely as laws intended to interfere with religious exercise;"],[1,"(3) governments should not substantially burden religious exercise without compelling justification;"],[1,"(4) in Employment Division v. Smith, 494 U.S. 872 (1990) the Supreme Court virtually eliminated the requirement that the government justify burdens on religious exercise imposed by laws neutral toward religion; and"],[1,"(5) the compelling interest test as set forth in prior Federal court rulings is a workable test for striking sensible balances between religious liberty and competing prior governmental interests."],[0,"(b) Purposes"],[0,"The purposes of this chapter are—"],[1,"(1) to restore the compelling interest test as set forth in Sherbert v. Verner, 374 U.S. 398 (1963) and Wisconsin v. Yoder, 406 U.S. 205 (1972) and to guarantee its application in all cases where free exercise of religion is substantially burdened; and"],[1,"(2) to provide a claim or defense to persons whose religious exercise is substantially burdened by government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000bb?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000bb. Congressional findings and declaration of purposes","tname":"The Public Health and Welfare","by":{"2":"11"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","by":{"2":"34"}},{"t":"usc","label":"18 U.S.C. § 3504","url":"https://www.law.cornell.edu/uscode/text/18/3504","subs":["(a)(1)","(a)(2)"],"by":{"2":"31, 31"}},{"t":"case","label":"ACLU Found. of So. Cal. v. Barr","cite":"952 F.2d 457","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/952/457/","by":{"3":"7, 46, 47","4":"7"}},{"t":"case","label":"Alderman v. United States","cite":"394 U.S. 165","y":1969,"id":"1967/133","sc":1,"ar":1,"sum":"In a majority opinion speaking for himself and four other members of the Court, Justice Byron R. White held that \"conversations as well as property are excludable from the criminal trial when they are found to be the fruits of an illegal invasion of the home.\" Moreover, continued White, \"surveillance records as to which any petitioner has standing to object should be turned over to him without being screened in camera by the trial judge.","sumSrc":"Oyez","by":{"3":"45, 52, 53","4":"16"}},{"t":"case","label":"Am. Elec. Power Co., Inc. v. Connecticut","cite":"564 U.S. 410","y":2011,"id":"2010/10-174","sc":1,"sum":"The Court held that held the Clean Air Act bars suits by governmental bodies and private parties seeking to curb emissions from utilities via the federal common law.","sumSrc":"Oyez","by":{"3":"52"}},{"t":"case","label":"Bank Line Ltd. v. United States","cite":"68 F. Supp. 587","y":1946,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./68/587/","by":{"3":"29"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"3":"44"}},{"t":"case","label":"Bostock v. Clayton County","cite":"140 S Ct. 1731","y":2020,"url":"https://www.courtlistener.com/c/S%20Ct./140/1731/","by":{"3":"42"}},{"t":"case","label":"City of Milwaukee v. Illinois & Michigan","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"52"}},{"t":"case","label":"Cogen v. United States","cite":"278 U.S. 221","y":1929,"id":"scdb/1928-121","sc":1,"sum":"An application by a defendant in a criminal case, after indictment and before trial, for a summary order requiring the United States Attorney to return papers taken from the defendant without a warrant, and for the suppression of all evidence obtained therefrom, held not to be an independent proceeding; the order of the District Court denying the application held interlocutory and not independently appealable. 24 F. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"43"}},{"t":"case","label":"Commodity Futures Trading Comm’n v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"37"}},{"t":"case","label":"Cresmer v. United States","cite":"9 F.R.D. 203","y":1949,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.R.D./9/203/","by":{"3":"29"}},{"t":"case","label":"CSX Transp., Inc. v. Alabama Dep’t of Revenue","cite":"562 U.S. 277","y":2011,"id":"2010/09-520","sc":1,"sum":"The Court held that a railroad company could invoke the Railroad Revitalization and Regulatory Reform Act to challenge sales and use taxes that apply to rail carriers, but exempt their competitors in the transportation industry.","sumSrc":"Oyez","by":{"3":"44"}},{"t":"case","label":"Dellums v. Powell","cite":"561 F.2d 242","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/561/242/","by":{"3":"54"}},{"t":"case","label":"Emp’t Div. v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"sum":"The Court held that the First Amendment does not protect individuals engaging in illegal acts as part of a religious ceremony.","sumSrc":"Oyez","by":{"3":"64"}},{"t":"case","label":"Ethyl Corp. v. Envtl. Prot. Agency","cite":"478 F.2d 47","y":1973,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/478/47/","by":{"3":"54","4":"11"}},{"t":"case","label":"Firth Sterling Steel Co. v. Bethlehem Steel Co.","cite":"199 F. 353","y":1912,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F./199/353/","by":{"3":"28"}},{"t":"case","label":"Grant Brothers Constr. Co. v. United States","cite":"232 U.S. 647","y":1914,"id":"scdb/1913-204","sc":1,"sum":"An action by the United States to recover penalties under the Alien Contract Labor Law is civil and attended with the usual incidents of a civil action. United States v. Regan, ante, p. 37.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"43"}},{"t":"case","label":"Halpern v. United States","cite":"258 F.2d 36","y":1958,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/258/36/","sum":"Holding that statute displaced the privilege “dependent upon the availability and adequacy of other methods of protecting the overriding interest of national security”.","sumSrc":"brief:3","by":{"3":"57","4":"12, 13"}},{"t":"case","label":"Jabara v. Kelley","cite":"75 F.R.D. 475","y":1977,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.R.D./75/475/","by":{"3":"57"}},{"t":"case","label":"Jabara v. Webster","cite":"691 F.2d 272","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/691/272/","by":{"3":"56, 57","4":"12"}},{"t":"case","label":"Mobil Oil Corp. v. Higginbotham","cite":"436 U.S. 618","y":1978,"id":"1977/76-1726","sc":1,"sum":"In an action for wrongful death on the high seas, the measure of damages is governed by the Death on the High Seas Act, 46 U. S. C. § 762, which limits a decedent's survivors' recovery to their \"pecuniary loss,\" and hence the survivors are not entitled to recover additional damages under general maritime law for \"loss of society.\" Pp. 620-626. 545 F. 2d 422, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"49"}},{"t":"case","label":"N.L.R.B. v. Robbins Tire & Rubber Co.","cite":"437 U.S. 214","y":1978,"id":"1977/77-911","sc":1,"sum":"The Court of Appeals erred in holding that the NLRB was not entitled to withhold the witness statements under Exemption 7 (A).","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"60"}},{"t":"case","label":"Olson Rug Co. v. NLRB","cite":"291 F.2d 655","y":1961,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/291/655/","op":2,"by":{"3":"54"}},{"t":"case","label":"Oncale v. Sundowner Offshore Services, Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"3":"42"}},{"t":"case","label":"Pollen v. Ford Instrument Co.","cite":"26 F. Supp. 583","y":1939,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./26/583/","by":{"3":"28"}},{"t":"case","label":"Rex v. Watson","cite":"2 Stark. 116","y":1817,"url":"https://www.courtlistener.com/c/Stark./2/116/","by":{"3":"29"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"3":"37"}},{"t":"case","label":"United States v. Aguilar","cite":"515 U.S. 593","y":1995,"id":"1994/94-270","sc":1,"sum":"The Supreme Court held that making false statements to an FBI agent who may or may not testify at trial is not sufficient to support a conviction for obstruction of justice. Aguilar’s conviction for disclosing a wiretap was proper, however, because the statute does not require that the wiretap is currently in force. The First Amendment did not require excluding expired wiretaps from the statute either.","sumSrc":"Oyez","by":{"3":"45"}},{"t":"case","label":"United States v. Coplon","cite":"185 F.2d 629","y":1950,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/185/629/","by":{"3":"32"}},{"t":"case","label":"United States v. Lyon","cite":"567 F.2d 777","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/567/777/","by":{"3":"54"}},{"t":"case","label":"United States v. Sioux Nation of Indians","cite":"448 U.S. 371","y":1980,"id":"1979/79-639","sc":1,"sum":"The Court held that Congress did not violate the doctrine of separation of powers and affirmed the Court of Claims decision. Writing for the majority, Justice Harry A. Blackmun noted a similar situation in Nock v. United States , where a congressional exemption from a judicial bar was ruled not to be in violation of separation of powers and upheld by the Court.","sumSrc":"Oyez","by":{"3":"38"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"3":"44"}},{"t":"case","label":"United States v. U.S. District Court (Keith)","cite":"407 U.S. 297","y":1972,"id":"1971/70-153","sc":1,"ar":1,"sum":"The Court held government officials were obligated to obtain a warrant before beginning electronic surveillance even if domestic security issues were involved. The \"inherent vagueness of the domestic security concept\" and the potential for abusing it to quell political dissent made the Fourth Amendment protections especially important when the government engaged in spying on its own citizens.","sumSrc":"Oyez","by":{"3":"23, 59, 62"}},{"t":"case","label":"Vance v. Terrazas","cite":"444 U.S. 252","y":1980,"id":"1979/78-1143","sc":1,"ar":1,"sum":"Section 349 (a) (2) of the Immigration and Nationality Act provides that \"a person who is a national of the United States whether by birth or naturalization, shall lose his nationality by...taking an oath or making an affirmation or other formal declaration of allegiance to a foreign state or a political subdivision thereof.\" Section 349 (c) provides that the party claiming that such loss of citizenship occurred …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"59"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25, 26"}},{"t":"case","label":"Worthington v. Scribner","cite":"109 Mass. 487","y":1872,"url":"https://www.courtlistener.com/c/Mass./109/487/","by":{"3":"29"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"3":"5, 59"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"3":"59"}},{"t":"usc","label":"18 U.S.C. § 2712","url":"https://www.law.cornell.edu/uscode/text/18/2712","subs":["(b)(4)"],"by":{"3":"51, 51"}},{"t":"usc","label":"42 U.S.C. § 1985","url":"https://www.law.cornell.edu/uscode/text/42/1985","subs":["(3)"],"by":{"3":"13"}},{"t":"usc","label":"50 U.S.C. § 1802","url":"https://www.law.cornell.edu/uscode/text/50/1802","subs":["(a)(3)"],"stext":{"head":"§1802. Electronic surveillance authorization without court order; certification by Attorney General; reports to Congressional committees; transmittal under seal; duties and compensation of communication common carrier; applications; jurisdiction of court","paras":[[0,"(a)(1) Notwithstanding any other law, the President, through the Attorney General, may authorize electronic surveillance without a court order under this subchapter to acquire foreign intelligence information for periods of up to one year if the Attorney General certifies in writing under oath that—"],[1,"(A) the electronic surveillance is solely directed at—"],[2,"(i) the acquisition of the contents of communications transmitted by means of communications used exclusively between or among foreign powers, as defined in section 1801(a)(1), (2), or (3) of this title; or"],[2,"(ii) the acquisition of technical intelligence, other than the spoken communications of individuals, from property or premises under the open and exclusive control of a foreign power, as defined in section 1801(a)(1), (2), or (3) of this title;"],[1,"(B) there is no substantial likelihood that the surveillance will acquire the contents of any communication to which a United States person is a party; and"],[1,"(C) the proposed minimization procedures with respect to such surveillance meet the definition of minimization procedures under section 1801(h) of this title; and"],[0,"if the Attorney General reports such minimization procedures and any changes thereto to the House Permanent Select Committee on Intelligence and the Senate Select Committee on Intelligence at least thirty days prior to their effective date, unless the Attorney General determines immediate action is required and notifies the committees immediately of such minimization procedures and the reason for their becoming effective immediately."],[0,"(2) An electronic surveillance authorized by this subsection may be conducted only in accordance with the Attorney General's certification and the minimization procedures adopted by him. The Attorney General shall assess compliance with such procedures and shall report such assessments to the House Permanent Select Committee on Intelligence and the Senate Select Committee on Intelligence under the provisions of section 1808(a) of this title."],[0,"(3) The Attorney General shall immediately transmit under seal to the court established under section 1803(a) of this title a copy of his certification. Such certification shall be maintained under security measures established by the Chief Justice with the concurrence of the Attorney General, in consultation with the Director of National Intelligence, and shall remain sealed unless—"],[1,"(A) an application for a court order with respect to the surveillance is made under sections 1801(h)(4) and 1804 of this title; or"],[1,"(B) the certification is necessary to determine the legality of the surveillance under section 1806(f) of this title."],[0,"(4) With respect to electronic surveillance authorized by this subsection, the Attorney General may direct a specified communication common carrier to—"],[1,"(A) furnish all information, facilities, or technical assistance necessary to accomplish the electronic surveillance in such a manner as will protect its secrecy and produce a minimum of interference with the services that such carrier is providing its customers; and"],[1,"(B) maintain under security procedures approved by the Attorney General and the Director of National Intelligence any records concerning the surveillance or the aid furnished which such carrier wishes to retain."],[0,"The Government shall compensate, at the prevailing rate, such carrier for furnishing such aid."],[0,"(b) Applications for a court order under this subchapter are authorized if the President has, by written authorization, empowered the Attorney General to approve applications to the court having jurisdiction under section 1803 of this title, and a judge to whom an application is made may, notwithstanding any other law, grant an order, in conformity with section 1805 of this title, approving electronic surveillance of a foreign power or an agent of a foreign power for the purpose of obtaining foreign intelligence information, except that the court shall not have jurisdiction to grant any order approving electronic surveillance directed solely as described in paragraph (1)(A) of subsection (a) unless such surveillance may involve the acquisition of communications of any United States person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1802?type=usc&year=mostrecent&link-type=html"},"head":"§1802. Electronic surveillance authorization without court order; certification by Attorney General; reports to Congressional committees; transmittal under seal; duties and compensation of communication common carrier; applications; jurisdiction of court","tname":"War and National Defense","by":{"3":"60","4":"14"}},{"t":"case","label":"ACLU v. NSA","cite":"493 F.3d 644","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/493/644/","by":{"4":"19"}},{"t":"case","label":"Abilt v. CIA","cite":"848 F.3d 305","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/305/","by":{"4":"20"}},{"t":"case","label":"Al-Haramain Islamic Found., Inc. v. Bush","cite":"507 F.3d 1190","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/507/1190/","by":{"4":"19"}},{"t":"case","label":"Attkisson v. Holder","cite":"925 F.3d 606","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/925/606/","by":{"4":"9"}},{"t":"case","label":"Baker & Hostetler LLP v. United States Dep’t of Commerce","cite":"473 F.3d 312","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/473/312/","by":{"4":"14"}},{"t":"case","label":"Bowles v. United States","cite":"950 F.2d 154","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/950/154/","by":{"4":"20"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"4":"9"}},{"t":"case","label":"Clift v. United States","cite":"597 F.2d 826","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/597/826/","sum":"Upholding claim of state-secrets privilege in proceeding under the Invention Secrecy Act where privileged information could not be shared with inventor.","sumSrc":"brief:4","by":{"4":"13"}},{"t":"case","label":"(I) Cases—Continued: Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"op":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"4":"18"}},{"t":"case","label":"DTM Research, L.L.C. v. AT&T Corp.","cite":"245 F.3d 327","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/245/327/","by":{"4":"20"}},{"t":"case","label":"Ellsberg v. Mitchell","cite":"709 F.2d 51","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/709/51/","ar":1,"by":{"4":"20"}},{"t":"case","label":"Farnsworth Cannon, Inc. v. Grimes","cite":"635 F.2d 268","y":1980,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/635/268/","by":{"4":"20"}},{"t":"case","label":"General Eng’g, Inc. v. NLRB","cite":"341 F.2d 367","y":1965,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/341/367/","by":{"4":"11"}},{"t":"case","label":"Guong v. United States","cite":"860 F.2d 1063","y":1988,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/860/1063/","by":{"4":"20"}},{"t":"case","label":"J.H. Rutter Rex Mfg. Co. v. NLRB","cite":"473 F.2d 223","y":1973,"url":"https://www.courtlistener.com/c/F.2d/473/223/","by":{"4":"11"}},{"t":"case","label":"Salisbury v. United States","cite":"690 F.2d 966","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/690/966/","by":{"4":"20"}},{"t":"case","label":"United States v. Ajlouny","cite":"629 F.2d 830","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/629/830/","by":{"4":"11"}},{"t":"case","label":"United States v. Brown","cite":"484 F.2d 418","y":1973,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/484/418/","by":{"4":"11"}},{"t":"case","label":"United States v. Butenko","cite":"494 F.2d 593","y":1974,"url":"https://www.courtlistener.com/c/F.2d/494/593/","by":{"4":"11"}},{"t":"case","label":"Valdez v. NSA","cite":"228 F. Supp. 3d 1271","y":2017,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/228/1271/","by":{"4":"9"}},{"t":"case","label":"Weinberger v. Catholic Action of Hawaii/Peace Educ. Project","cite":"454 U.S. 139","y":1981,"id":"1981/81-1377","sc":1,"ar":1,"sum":"The Court of Appeals erred in requiring the Navy to prepare and release to the public a \"Hypothetical Environmental Impact Statement.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"19, 21"}},{"t":"case","label":"Wikimedia Found. v. NSA","cite":"2021 WL 4187840","y":2021,"court":"4th Cir. Sept. 15","op":2,"by":{"4":"2, 10, 19"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(b)(5)"],"by":{"4":"14, 14"}},{"t":"usc","label":"35 U.S.C. § 181","url":"https://www.law.cornell.edu/uscode/text/35/181","by":{"4":"12, 13"}},{"t":"usc","label":"42 U.S.C. § 4321","url":"https://www.law.cornell.edu/uscode/text/42/4321","by":{"4":"21"}},{"t":"usc","label":"35 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/35/1","by":{"4":"12"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","subs":["(b)(1)"],"by":{"4":"6"}}]};